@@ -0,0 +1,27 @@
+package ledger
+
+import "testing"
+
+func TestBalanceMultiplePostings(t *testing.T) {
+	l := &Ledger{}
+
+	// Post 1: credit 300 to account "a", debit 300 from account "x"
+	if err := l.Post(
+		Entry{AccountID: "a", AmountCents: 300, Currency: "EUR"},
+		Entry{AccountID: "x", AmountCents: -300, Currency: "EUR"},
+	); err != nil {
+		t.Fatal(err)
+	}
+
+	// Post 2: debit 100 from account "a", credit 100 to account "y"
+	if err := l.Post(
+		Entry{AccountID: "a", AmountCents: -100, Currency: "EUR"},
+		Entry{AccountID: "y", AmountCents: 100, Currency: "EUR"},
+	); err != nil {
+		t.Fatal(err)
+	}
+
+	if got := l.Balance("a"); got != 200 {
+		t.Fatalf("balance(a) = %d, want 200", got)
+	}
+}
